import requests

url = "https://africa-api.p.rapidapi.com/africa/api/v1/africa/tourism"
querystring = {"country_name": "kenya"}

headers = {
            "X-RapidAPI-Key": "SIGN-UP-FOR-KEY",
            "X-RapidAPI-Host": "africa-api.p.rapidapi.com"
        }

response = requests.get(url, headers=headers, params=querystring)
print(response.json())

